ruleSearch.bookList:
@js:(function(){
  var j=jget(result); if(!j) return [];
  var out=[];
  function toNum(v){ var n=Number(v); return isNaN(n)?0:n; }
  function fmtDur(d){ d=toNum(d); if(d<=0) return ''; if(d>1000) d=Math.round(d/1000); var m=Math.floor(d/60), s=d%60; return m+'分'+(s<10?'0':'')+s+'秒'; }
  function pick(o,p){ try{ var c=o; for(var i=0;i<p.length;i++){ if(c==null) return ''; c=c[p[i]]; } return (c==null?'':String(c)); }catch(e){ return ''; } }
  function jget(s){ try{ return JSON.parse(String(s||'')); }catch(e){ return null; } }
  var songs=findSongs(j);
  for(var i=0;i<songs.length;i++){ var t=songs[i]; var k=pick(t,['key'])||pick(t,['id']);
    if(!k) continue;
    var nm=pick(t,['name'])||pick(t,['title'])||pick(t,['song_name']);
    if(!nm) continue;
    out.push({
      name: nm,
      author: pick(t,['artistName'])||pick(t,['artist_name'])||pick(t,['singer']),
      coverUrl: pick(t,['image'])||pick(t,['thumbnail'])||pick(t,['avatar']),
      bookUrl: 'https://graph.nhaccuatui.com/api/v1/song/detail/'+String(k)+'?key='+String(k)+'&isDailyMix=false&timestamp='+Date.now(),
      lastChapter: fmtDur(pick(t,['duration']))
    });
  }
  return out;
  function findSongs(root){
    var res=[];
    walk(root,0);
    return res;
    function walk(n,d){
      if(d>6||n==null) return;
      if(n instanceof Array){
        for(var i=0;i<n.length;i++){ if(isSong(n[i])) res.push(n[i]); else walk(n[i],d+1); }
        return;
      }
      if(typeof n==='object'){
        if(isSong(n)){ res.push(n); return; }
        for(var k in n){ if(n.hasOwnProperty(k)) walk(n[k],d+1); }
      }
    }
    function isSong(o){
      if(o==null||typeof o!=='object') return false;
      var hasKey=(o.key!=null)||(o.id!=null);
      var hasName=(o.name!=null)||(o.title!=null)||(o.song_name!=null);
      return hasKey&&hasName;
    }
  }
})();

ruleExplore.bookList:
@js:(function(){
  var raw=String(result||'');
  var j=jget(raw);
  var out=[];
  function toNum(v){ var n=Number(v); return isNaN(n)?0:n; }
  function fmtDur(d){ d=toNum(d); if(d<=0) return ''; if(d>1000) d=Math.round(d/1000); var m=Math.floor(d/60), s=d%60; return m+'分'+(s<10?'0':'')+s+'秒'; }
  function pick(o,p){ try{ var c=o; for(var i=0;i<p.length;i++){ if(c==null) return ''; c=c[p[i]]; } return (c==null?'':String(c)); }catch(e){ return ''; } }
  function jget(s){ try{ return JSON.parse(String(s||'')); }catch(e){ return null; } }
  if(j){
    var items=j.items||(j.data&&j.data.items)||[];
    for(var i=0;i<items.length;i++){ var t=items[i];
      var k=pick(t,['key'])||pick(t,['id']); var nm=pick(t,['name'])||pick(t,['title']);
      if(!k||!nm) continue;
      out.push({
        name: nm,
        author: pick(t,['artistName'])||pick(t,['artist_name'])||pick(t,['singer']),
        coverUrl: pick(t,['image'])||pick(t,['thumbnail']),
        bookUrl: 'https://graph.nhaccuatui.com/api/v1/song/detail/'+String(k)+'?key='+String(k)+'&isDailyMix=false&timestamp='+Date.now(),
        lastChapter: fmtDur(pick(t,['duration']))
      });
    }
  }
  if(out.length) return out;
  if(j){
    var s2=[];
    (function walk(n,d){ if(d>6||n==null) return;
      if(n instanceof Array){ for(var i=0;i<n.length;i++){ if(isS(n[i])) s2.push(n[i]); else walk(n[i],d+1);} return; }
      if(typeof n==='object'){ if(isS(n)){ s2.push(n); return; } for(var k in n){ if(n.hasOwnProperty(k)) walk(n[k],d+1); } }
    })(j,0);
    function isS(o){ return o&&typeof o==='object'&&((o.key!=null)||(o.id!=null))&&((o.name!=null)||(o.title!=null)); }
    for(var m=0;m<s2.length;m++){ var t2=s2[m];
      var k2=pick(t2,['key'])||pick(t2,['id']);
      out.push({
        name: pick(t2,['name'])||pick(t2,['title']),
        author: pick(t2,['artistName'])||pick(t2,['artist_name']),
        coverUrl: pick(t2,['image'])||pick(t2,['thumbnail']),
        bookUrl: 'https://graph.nhaccuatui.com/api/v1/song/detail/'+String(k2)+'?key='+String(k2)+'&isDailyMix=false&timestamp='+Date.now(),
        lastChapter: fmtDur(pick(t2,['duration']))
      });
    }
  }
  if(out.length) return out;
  var head='⚠️ 未解析出歌曲';
  if(!raw){ head='❌ 无返回（请求失败或被拦截）'; }
  else if(raw.indexOf('Request denied')>=0||raw.indexOf('403')>=0){ head='❌ 被拦截（403/网关拒绝）'; }
  else if(raw.indexOf('<html')>=0){ head='❌ 返回HTML页面（可能需验证）'; }
  else if(!j){ head='⚠️ 非JSON返回'; }
  else { head='⚠️ 接口通但无歌曲（榜单key可能已变更）'; }
  return [{name:head, author:raw?raw.substring(0,300):'（空响应）', coverUrl:'', bookUrl:'', lastChapter:''}];
})();

ruleToc.chapterList:
@js:(function(){
  var s=String((typeof java!=='undefined'&&java.baseUrl)||(typeof baseUrl!=='undefined'?baseUrl:'')||'');
  var m=s.match(/[?&]key=([^&]+)/);
  if(!m||!m[1]){ m=s.match(/song\/detail\/([^?&]+)/); }
  if(!m||!m[1]) return [];
  var k=m[1];
  var arr=[{name:'▶ 播放', url:s}];
  arr.push({name:'📝 歌词', url:'https://graph.nhaccuatui.com/api/v1/song/lyric/detail?songKey='+k+'&timestamp='+Date.now()+'#lyric'});
  return arr;
})();

ruleContent.content:
@js:(function(){
  var s=String((typeof java!=='undefined'&&java.baseUrl)||(typeof baseUrl!=='undefined'?baseUrl:'')||'');
  try{
    if(s.indexOf('#lyric')>=0) return lyric(s);
    return audio(s);
  }catch(e){ return ''; }

  function audio(url){
    var r=String(result||'');
    if(!r){
      try{ r=String(java.ajax(url)); }catch(e0){ r=''; }
    }
    var j=jget(r); if(!j) return '';
    var list=[];
    (function walk(n,d){ if(d>6||n==null) return;
      if(n instanceof Array){ for(var i=0;i<n.length;i++){ if(isStream(n[i])) list.push(n[i]); else walk(n[i],d+1);} return; }
      if(typeof n==='object'){ if(isStream(n)){ list.push(n); return; } for(var k in n){ if(n.hasOwnProperty(k)) walk(n[k],d+1); } }
    })(j,0);
    function isStream(o){ return o&&typeof o==='object'&&(o.stream!=null||o.streamUrl!=null||o.file_url!=null||o.url!=null)&&(o.type!=null||o.quality!=null||o.bitrate!=null); }
    if(!list.length){
      // 没有 streamURL 结构时，兜底找任意 http 音频链接
      var m=String(r).match(/https?:[^"'\\ ]{10,300}?\.(?:mp3|m4a|aac|flac)(?:[^'"\\ ]*)/i);
      return m?m[0]:'';
    }
    var best='',bv=-1;
    for(var i=0;i<list.length;i++){
      var it=list[i];
      // 只取免费档：onlyVIP 为 true 的跳过
      if(it.onlyVIP===true||it.only_vip===true||it.vip===true) continue;
      var u=it.stream||it.streamUrl||it.file_url||it.url||'';
      if(!u) continue;
      var q=String(it.type||it.quality||it.bitrate||'');
      var v=0;
      if(/320/.test(q)) v=3;
      else if(/lossless|flac/i.test(q)) v=4;
      else if(/128/.test(q)) v=2;
      else v=1;
      if(v>bv){bv=v;best=u;}
    }
    return best||'';
  }

  function lyric(url){
    var r='';
    try{ r=String(java.ajax(url)); }catch(e){ r=''; }
    var j=jget(r); if(!j) return '（歌词获取失败）';
    var t='';
    (function walk(n,d){ if(t||d>6||n==null) return;
      if(typeof n==='string'){ if(n.length>20&&/[\u4e00-\u9fa5a-zA-Z]/.test(n)) { t=n; return; } return; }
      if(n instanceof Array){ for(var i=0;i<n.length;i++) walk(n[i],d+1); return; }
      if(typeof n==='object'){ for(var k in n){ if(n.hasOwnProperty(k)) walk(n[k],d+1); } }
    })(j,0);
    return t||'（无歌词）';
  }
})();
